import { getCoreRowModel } from '@tanstack/react-table';
import clsx from 'clsx';
import React, { forwardRef, type PropsWithChildren } from 'react';

import { DataTableV2DefaultCell } from './components/DataTableV2DefaultCell.js';
import { DataTableV2VirtualizationContainer } from './components/DataTableV2VirtualizationContainer.js';
import { DataTableV2ContextProvider } from './contexts/DataTableV2Context.js';
import { dataTableV2CSS, dataTableV2FullWidthCSS } from './DataTableV2.sty.js';
import { useDataTableV2ConfigRef } from './features/Config.js';
import { useColumnLineWrap } from './features/LineWrap.js';
import { useLoadingState } from './features/LoadingState.js';
import {
  DataTableV2Pagination,
  usePagination,
} from './features/Pagination/Pagination.js';
import { _DataTableV2PaginationInternal } from './features/Pagination/PaginationInternal.js';
import {
  DataTableV2CellActions,
  DataTableV2ColumnActions,
  DataTableV2RowActions,
  useUserActions,
} from './features/UserActions.js';
import { useVisualVariant } from './features/VisualVariants.js';
import { useColumns } from './hooks/useColumns.js';
import type { CoreOptions } from './hooks/useTable/createTable.js';
import type { TableOptions } from './hooks/useTable/types.js';
import { useTable } from './hooks/useTable/useTable.js';
import { type DataTableV2Props, type DataTableV2Ref } from './public.api.js';

function _InternalDataTable<T>(
  props: PropsWithChildren<DataTableV2Props<T>>,
  forwardedRef: React.Ref<DataTableV2Ref>,
) {
  // Hook used to adapt column definition for internal usage
  const [columns, consumerColumnDefMap] = useColumns<T>(props.columns, {});

  const options: TableOptions<T> = {
    columns,
    data: props.data,
    // In order to keep the types in our own realm, the cast to align with our
    // CoreOptions is necessary.
    getCoreRowModel: getCoreRowModel() as CoreOptions<T>['getCoreRowModel'],
  };

  useColumnLineWrap(props, options);
  useVisualVariant(props, options);
  useUserActions<T>(props, options, consumerColumnDefMap);
  usePagination(props, options);
  useLoadingState(props, options);

  const table = useTable<T>(options);

  const tableRef = useDataTableV2ConfigRef({ forwardedRef });

  return (
    <div
      ref={tableRef}
      className={clsx(
        dataTableV2CSS,
        { [dataTableV2FullWidthCSS]: props.fullWidth },
        props.className,
      )}
      style={props.style}
      data-testid={props['data-testid']}
    >
      <DataTableV2ContextProvider value={table}>
        {/* TODO: Position slot for the toolbar */}
        <DataTableV2VirtualizationContainer table={table} />

        {table.options.enablePagination === true ? (
          // eslint-disable-next-line react/jsx-pascal-case
          <_DataTableV2PaginationInternal
            pageSizeOptions={table.options.availablePaginationOptions ?? []}
            pageSize={table.getState().pagination.pageSize}
            onPageSizeChange={table.setPageSize}
            pageCount={table.getPageCount()}
            pageIndex={table.getState().pagination.pageIndex}
            onPageIndexChange={table.setPageIndex}
            enablePreviousPage={table.getState().pagination.enablePreviousPage}
            enableNextPage={table.getState().pagination.enableNextPage}
          />
        ) : null}
      </DataTableV2ContextProvider>
    </div>
  );
}

_InternalDataTable.displayName = 'DataTableV2';

const _DataTableV2Fwd = /* @__PURE__ */ forwardRef<
  DataTableV2Ref,
  PropsWithChildren<DataTableV2Props>
>(_InternalDataTable);

/**
 * The `DataTableV2` is a component for building tables which organize information
 * into rows and columns.
 */
export const DataTableV2 = Object.assign(_DataTableV2Fwd, {
  Pagination: DataTableV2Pagination,
  // UserActions: DataTableV2UserActions,
  ColumnActions: DataTableV2ColumnActions,
  CellActions: DataTableV2CellActions,
  RowActions: DataTableV2RowActions,
  DefaultCell: DataTableV2DefaultCell,
});
